#!/usr/bin/env bash
# Version-sources-agree gate (issue #212; mirrors c-RCP's
# `version-sources-agree` CI job, c-RCP/.github/workflows/ci.yml:251, and its
# release-time version-match gate, c-RCP/.github/workflows/release.yml:87-116).
#
# rust-RCP's release version is hand-maintained in more than one place:
#
#   1. Cargo.toml `[package] version`  (the canonical source; the binary's
#      `--version`/`capabilities` output reads it via CARGO_PKG_VERSION)
#   2. Cargo.lock's entry for this package (regenerated by cargo, but a
#      stale committed lock makes `--locked` builds fail or mislabel)
#   3. CHANGELOG.md's top `## vX.Y.Z` entry
#   4. any `pub const ...VERSION: &str = "X.Y.Z"` crate-version constant in
#      src/ (there is none today -- SPEC_VERSION/RELAY_SPEC_VERSION are the
#      RELAY spec version, not the crate version, and are deliberately not
#      X.Y.Z-shaped -- but one added later is checked automatically)
#
# and, at release time only,
#
#   5. the git tag being released (`vX.Y.Z`), passed as $1.
#
# Nothing used to check these against each other, which is how Cargo.toml
# reached 5.11.0 while the newest tag/GitHub Release was still v2.0.0: every
# SBOM/provenance artifact `rsfusa release` generated was labelled with a
# version that was never released.
#
# Usage:
#   bash scripts/version-sources-check.sh            # CI: sources 1-4 agree
#   bash scripts/version-sources-check.sh v5.11.0    # release: 1-4 agree AND == tag
set -euo pipefail

cd "$(dirname "$0")/.."

semver='[0-9]+\.[0-9]+\.[0-9]+'

pkg_name=$(awk '/^\[package\]/{p=1;next} /^\[/{p=0} p && /^name *=/{gsub(/.*= *"|".*/,"");print;exit}' Cargo.toml)
cargo_version=$(awk '/^\[package\]/{p=1;next} /^\[/{p=0} p && /^version *=/{gsub(/.*= *"|".*/,"");print;exit}' Cargo.toml)
lock_version=$(awk -v n="$pkg_name" '/^\[\[package\]\]/{m=0} $0=="name = \""n"\""{m=1} m && /^version = /{gsub(/.*= *"|".*/,"");print;exit}' Cargo.lock)
changelog_version=$(grep -m1 -oE "^## v${semver}" CHANGELOG.md | grep -oE "${semver}" || true)

echo "Cargo.toml [package] version      : ${cargo_version:-<not found>} (package ${pkg_name:-<not found>})"
echo "Cargo.lock [package] version      : ${lock_version:-<not found>}"
echo "CHANGELOG.md top entry            : ${changelog_version:-<not found>}"

fail=0
[ -n "$cargo_version" ] || { echo "::error file=Cargo.toml::Could not parse [package] version"; fail=1; }
[ -n "$lock_version" ] || { echo "::error file=Cargo.lock::Could not find a [[package]] entry for ${pkg_name}"; fail=1; }
[ -n "$changelog_version" ] || { echo "::error file=CHANGELOG.md::Could not parse a top '## vX.Y.Z' entry"; fail=1; }
[ "$fail" -eq 0 ] || exit 1

if [ "$lock_version" != "$cargo_version" ]; then
  echo "::error file=Cargo.lock::Cargo.lock records ${pkg_name} ${lock_version}, Cargo.toml says ${cargo_version} -- run 'cargo update -p ${pkg_name}' and commit Cargo.lock."
  fail=1
fi
if [ "$changelog_version" != "$cargo_version" ]; then
  echo "::error file=CHANGELOG.md::CHANGELOG.md's top entry is v${changelog_version}, Cargo.toml says ${cargo_version} -- bump both together."
  fail=1
fi

# Crate-version constants in src/: any `const FOO_VERSION: &str = "X.Y.Z"`.
while IFS= read -r hit; do
  [ -n "$hit" ] || continue
  file=${hit%%:*}
  const_version=$(echo "$hit" | grep -oE "\"${semver}\"" | tr -d '"')
  echo "version constant ${hit}"
  if [ "$const_version" != "$cargo_version" ]; then
    echo "::error file=${file}::Version constant says ${const_version}, Cargo.toml says ${cargo_version} -- prefer env!(\"CARGO_PKG_VERSION\") over a hand-maintained copy."
    fail=1
  fi
done < <(grep -rnE "const [A-Z_]*VERSION: *&str *= *\"${semver}\"" src || true)

if [ $# -ge 1 ]; then
  tag="$1"
  tag_version="${tag#v}"
  echo "git tag being released            : ${tag}"
  if ! echo "$tag_version" | grep -qxE "${semver}"; then
    echo "::error::Tag '${tag}' is not of the form vX.Y.Z"
    fail=1
  elif [ "$tag_version" != "$cargo_version" ]; then
    echo "::error::Tag ${tag} does not match Cargo.toml version ${cargo_version} -- every SBOM/provenance artifact and the crates.io upload for this tag would be labelled ${cargo_version}. Bump Cargo.toml/Cargo.lock/CHANGELOG.md to ${tag_version} (or tag v${cargo_version}) and re-tag."
    fail=1
  fi
fi

if [ "$fail" -ne 0 ]; then
  echo "Version sources disagree (see errors above)."
  exit 1
fi
echo "OK: all version sources agree on ${cargo_version}"
